const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

function allSplits(text, opts) {
  const whole = parse(text, opts);
  for (let a = 0; a <= text.length; a++) {
    for (let b = a; b <= text.length; b++) {
      const p = createParser(opts);
      const r = [];
      for (const c of [text.slice(0, a), '', text.slice(a, b), text.slice(b)]) r.push(...p.push(c));
      r.push(...p.end());
      assert.deepEqual(r, whole, JSON.stringify([text, a, b]));
    }
  }
  return whole;
}
function lineOf(fn) {
  try { fn(); } catch (e) { assert(e instanceof SyntaxError, String(e)); return /line (\d+)/.exec(e.message)[1] | 0; }
  throw new Error('no throw');
}
function errSplits(text, n) {
  for (let a = 0; a <= text.length; a++) {
    const p = createParser();
    assert.equal(lineOf(() => { p.push(text.slice(0, a)); p.push(text.slice(a)); p.end(); }), n, JSON.stringify([text, a]));
  }
}

assert.deepEqual(allSplits(''), []);
assert.deepEqual(allSplits('\uFEFF'), []);
assert.deepEqual(allSplits('\n'), [['']]);
assert.deepEqual(allSplits('\n\n'), [[''], ['']]);
assert.deepEqual(allSplits('a\r\nb\rc\nd'), [['a'], ['b'], ['c'], ['d']]);
assert.deepEqual(allSplits('a\r\n'), [['a']]);
assert.deepEqual(allSplits('\uFEFFa,\uFEFF'), [['a', '\uFEFF']]);
assert.deepEqual(allSplits('"x""y","a\r\nb\rc",z"q"\n'), [['x"y', 'a\r\nb\rc', 'z"q"']]);
assert.deepEqual(allSplits('"",""""\r\n,'), [['', '"'], ['', '']]);
assert.deepEqual(allSplits('a;b,c', { delimiter: ';' }), [['a', 'b,c']]);
assert.deepEqual(allSplits('a\tb', { delimiter: '\t' }), [['a', 'b']]);
assert.deepEqual(allSplits('\uD83D\uDE00,x'), [['\uD83D\uDE00', 'x']]);
